"""Restore only the reviewed publication wiring for the inherited proof."""
OLD_HEADER = "  publish-release:\n    needs: [changes, linux, rust-1-88, sf08-browser, release-plan, jetbrains, vscode-package, nagi-package, nagi-regression]\n    if: >-\n      always() && github.event_name == 'push' && github.ref == 'refs/heads/main' &&\n      (\n        (needs.linux.result == 'success' && needs.rust-1-88.result == 'success' &&\n         needs.sf08-browser.result == 'success') ||\n        (needs.release-plan.outputs.release_jetbrains == 'true' &&\n         needs.release-plan.outputs.release_nagi != 'true' &&\n         needs.release-plan.outputs.release_vscode != 'true' &&\n         needs.linux.result == 'skipped' &&\n         needs.rust-1-88.result == 'skipped' &&\n         needs.sf08-browser.result == 'skipped')\n      ) && needs.release-plan.result == 'success' &&\n      needs.changes.result == 'success' &&\n      (needs.jetbrains.result == 'success' || needs.jetbrains.result == 'skipped') &&\n      (needs.vscode-package.result == 'success' || needs.vscode-package.result == 'skipped') &&\n      (needs.nagi-package.result == 'success' || needs.nagi-package.result == 'skipped') &&\n      ((needs.release-plan.outputs.package_nagi == 'true' && needs.nagi-regression.result == 'success') ||\n       (needs.release-plan.outputs.package_nagi == 'false' && needs.nagi-regression.result == 'skipped')) &&\n      (needs.release-plan.outputs.release_nagi != 'true' || needs.nagi-regression.result == 'success') &&\n      (needs.release-plan.outputs.release_jetbrains != 'true' || needs.jetbrains.result == 'success') &&\n      (needs.release-plan.outputs.release_vscode != 'true' || needs.vscode-package.result == 'success') &&\n      (needs.release-plan.outputs.release_nagi != 'true' || needs.nagi-package.result == 'success') &&\n      (needs.release-plan.outputs.release_vscode == 'true' || needs.release-plan.outputs.release_nagi == 'true' || needs.release-plan.outputs.release_jetbrains == 'true')\n"
NEW_HEADER = "  publish-release:\n    needs: [changes, ci-plan, critical, linux, rust-1-88, sf08-browser, release-plan, jetbrains, vscode-package, nagi-package, nagi-regression, ready]\n    if: >-\n      always() && github.event_name == 'push' && github.ref == 'refs/heads/main' &&\n      needs.ready.result == 'success' && needs.ci-plan.result == 'success' &&\n      needs.ci-plan.outputs.level == '3' && needs.release-plan.result == 'success' &&\n      (needs.release-plan.outputs.release_vscode == 'true' || needs.release-plan.outputs.release_nagi == 'true' || needs.release-plan.outputs.release_jetbrains == 'true')\n"
GATE = '      - name: Require exact-source level-3 publication gate # ci-publication\n        env:\n          NAGI_CI_NEEDS: ${{ toJSON(needs) }}\n        run: python -B scripts/ci/publication_gate.py\n'

def inverse_publication(source):
    if source.count(NEW_HEADER) != 1 or source.count(GATE) != 1:
        raise ValueError('missing, duplicated or changed publication gate')
    return source.replace(NEW_HEADER, OLD_HEADER, 1).replace(GATE, '', 1)
